"""
Elasticsearch service for hybrid search (BM25 + vector + RRF).
Implements the core retrieval functionality with proper index mapping.
"""
import logging
from typing import List, Dict, Any, Optional
from elasticsearch import Elasticsearch, AsyncElasticsearch

from config import get_settings

logger = logging.getLogger(__name__)


class ElasticsearchService:
    """Elasticsearch operations for hybrid search."""

    INDEX_MAPPING = {
        "mappings": {
            "properties": {
                "project_id": {"type": "keyword"},
                "doc_id": {"type": "keyword"},
                "chunk_id": {"type": "keyword"},
                "doc_title": {"type": "text"},
                "text": {"type": "text"},
                "page": {"type": "integer"},
                "vector": {
                    "type": "dense_vector",
                    "dims": 768,
                    "index": True,
                    "similarity": "cosine"
                }
            }
        }
    }

    def __init__(self):
        settings = get_settings()
        self.client = Elasticsearch(
            hosts=[settings.elasticsearch_url],
            api_key=settings.elasticsearch_api_key
        )
        self.index_name = f"{settings.elasticsearch_index_prefix}-documents"

    async def hybrid_search(
        self,
        query: str,
        vector: List[float],
        project_id: str,
        k: int = 5
    ) -> List[Dict]:
        """Hybrid search with BM25 + kNN + RRF."""
        response = self.client.search(
            index=self.index_name,
            body={
                "size": k,
                "query": {
                    "bool": {
                        "must": [{"match": {"text": query}}],
                        "filter": [{"term": {"project_id": project_id}}]
                    }
                },
                "knn": {
                    "field": "vector",
                    "query_vector": vector,
                    "k": k,
                    "num_candidates": 100
                },
                "rank": {"rrf": {"window_size": 100}}
            }
        )

        return [hit["_source"] for hit in response["hits"]["hits"]]
